import numeral from 'numeral';
import { isNil } from 'lodash';
import { Maskers } from '../';
import { ERRORS } from './';

const validNumberRegex = /^-?[0-9]*(\.?[0-9]*)?$/;

function numberValidator({ errors, value }) {
  if (!isNil(value) && value !== '') {
    const maskedValue = Maskers.number(value).trim();
    const newValue = numeral(maskedValue).value();

    if (
      isNil(newValue) ||
      isNaN(newValue) ||
      value.toString() !== maskedValue ||
      !validNumberRegex.test(maskedValue)
    ) {
      errors.push(ERRORS.invalidNumber);
    }
  }

  return errors;
}

export default numberValidator;
